rgin-top:14px"><article class="s10-card s10-span-6"><h2>Validate a Server Backup</h2><form method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?= backup_step18_h($csrf??'') ?>"><input type="hidden" name="action" value="validate_local"><label style="display:block;font-weight:800;margin-top:8px">Backup<select name="backup_id" required style="width:100%;padding:11px;margin-top:6px;border:1px solid #cedbd2;border-radius:11px"><option value="">Choose backup…</option><?php foreach($backups as $r):?><option value="<?= (int)$r['id'] ?>"><?= backup_step18_h($r['backup_code'].' • '.$r['created_at'].' • '.$r['verification_status']) ?></option><?php endforeach;?></select></label><label style="display:block;font-weight:800;margin-top:12px">Backup Passphrase<input type="password" name="passphrase" required minlength="12" autocomplete="off" style="width:100%;box-sizing:border-box;padding:11px;margin-top:6px;border:1px solid #cedbd2;border-radius:11px"></label><button class="os-btn primary" style="margin-top:14px">Validate & Preview</button></form></article><article class="s10-card s10-span-6"><h2>Upload an External Recovery Copy</h2><form method="post" enctype="multipart/form-data" autocomplete="off"><input type="hidden" name="csrf" value="<?= backup_step18_h($csrf??'') ?>"><input type="hidden" name="action" value="validate_upload"><label style="display:block;font-weight:800;margin-top:8px">.hwcbak File<input type="file" name="backup_file" accept=".hwcbak,application/octet-stream" required style="display:block;width:100%;margin-top:8px"></label><label style="display:block;font-weight:800;margin-top:12px">Backup Passphrase<input type="password" name="passphrase" required minlength="12" autocomplete="off" style="width:100%;box-sizing:border-box;padding:11px;margin-top:6px;border:1px solid #cedbd2;border-radius:11px"></label><button class="os-btn primary" style="margin-top:14px">Upload, Validate & Preview</button></form></article></section><?php else:$schemaOk=!