input type="password" name="current_password" required autocomplete="current-password" style="width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #cedbd2;border-radius:10px"></label><label style="display:block;font-weight:800;margin-top:10px">Type RESTORE DATABASE<input name="confirmation" required autocomplete="off" placeholder="RESTORE DATABASE" style="width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #cedbd2;border-radius:10px"></label><button class="os-btn primary" style="margin-top:14px">Create Rollback Point & Restore</button></form><?php else:?><div class="pp-alert bad">Restore is blocked because this package does not match the current application schema.</div><?php endif;?><a class="os-btn" style="margin-top:10px" href="backup_restore.php">Start Another Preview</a></aside></section><?php endif;?><div class="os-footer-note"><strong>After restore:</strong> all existing authenticated sessions are invalidated. Sign in again using a user account contained in the restored backup.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
